// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        (bool success,) = address(c).call{value: 1 ether}("");
        require(success, "deposit failed");

        assertEq(c.balances(alice), 1 ether);

        vm.prank(alice);
        c.withdraw();

        assertTrue(address(c).balance == 0);
    }
}
